<?php
namespace App\Features\Ai\Services;
use App\Features\Ai\Contracts\AiClientInterface; use Illuminate\Support\Facades\Http; use RuntimeException;
class OpenAiPostGeneratorService implements AiClientInterface { public function generate(string $prompt,int $count):array{$key=config('openai.api_key');if(!$key)throw new RuntimeException('OPENAI_API_KEY belum dikonfigurasi.');$response=Http::withToken($key)->timeout(90)->post(rtrim(config('openai.base_url'),'/').'/chat/completions',['model'=>config('openai.model'),'response_format'=>['type'=>'json_object'],'messages'=>[['role'=>'system','content'=>'Buat artikel blog berbahasa Indonesia. Balas JSON object dengan key articles berupa array; setiap item memiliki title, category, excerpt, content Markdown. Category harus salah satu: Teknologi, Pendidikan, Gaya Hidup, Bisnis, Opini, Umum.'],['role'=>'user','content'=>"Buat {$count} artikel tentang: {$prompt}. Kembalikan tepat {$count} artikel." ]],'temperature'=>0.7]);$response->throw();$json=$response->json('choices.0.message.content');$data=json_decode((string)$json,true);if(!is_array($data)||!is_array($data['articles']??null))throw new RuntimeException('Format respons AI tidak valid.');return array_slice(array_map(fn($a)=>['title'=>(string)($a['title']??''),'category'=>(string)($a['category']??'Umum'),'excerpt'=>(string)($a['excerpt']??''),'content'=>(string)($a['content']??'')],$data['articles']),0,$count);} }
